"""
Bounded FIFO task queue with priorities, cancellation, retries, and thread-safe wrapper.
"""

import threading
import heapq
import time
import uuid
from typing import Callable, Any, Optional, Dict, List, Tuple
from dataclasses import dataclass, field
from enum import Enum
from concurrent.futures import ThreadPoolExecutor
import unittest


class TaskState(Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"


@dataclass(order=True)
class Task:
    priority: int
    timestamp: float = field(compare=True)
    task_id: str = field(default_factory=lambda: str(uuid.uuid4()), compare=False)
    func: Callable = field(compare=False)
    args: tuple = field(default=(), compare=False)
    kwargs: dict = field(default_factory=dict, compare=False)
    state: TaskState = field(default=TaskState.PENDING, compare=False)
    retries: int = field(default=0, compare=False)
    max_retries: int = field(default=0, compare=False)
    result: Any = field(default=None, compare=False)
    exception: Optional[Exception] = field(default=None, compare=False)
    cancelled: bool = field(default=False, compare=False)

    def cancel(self):
        self.cancelled = True
        if self.state == TaskState.PENDING:
            self.state = TaskState.CANCELLED

    def __lt__(self, other):
        # Tie-break by timestamp for FIFO within same priority
        if self.priority != other.priority:
            return self.priority < other.priority
        return self.timestamp < other.timestamp


class TaskQueue:
    """Bounded FIFO task queue with priorities and cancellation support."""

    def __init__(self, max_size: int = 100):
        if max_size <= 0:
            raise ValueError("max_size must be positive")
        self._max_size = max_size
        self._heap: List[Task] = []
        self._lock = threading.Lock()
        self._not_empty = threading.Condition(self._lock)
        self._not_full = threading.Condition(self._lock)
        self._closed = False
        self._active_tasks: Dict[str, Task] = {}
        self._completed_tasks: Dict[str, Task] = {}
        self._cancelled_pending: set = set()

    @property
    def size(self) -> int:
        with self._lock:
            return len(self._heap)

    @property
    def max_size(self) -> int:
        return self._max_size

    def put(self, task: Task, block: bool = True, timeout: Optional[float] = None) -> bool:
        """
        Put a task into the queue. Returns True if queued, False if cancelled or queue closed.
        If the queue is full, blocks until space is available or timeout expires.
        """
        if self._closed:
            return False

        with self._not_full:
            while len(self._heap) >= self._max_size and not self._closed:
                if not block:
                    return False
                if timeout is not None:
                    if not self._not_full.wait(timeout):
                        return False
                else:
                    self._not_full.wait()

            if self._closed:
                return False

            # Check if task was cancelled before being queued
            if task.cancelled:
                task.state = TaskState.CANCELLED
                self._cancelled_pending.add(task.task_id)
                return False

            heapq.heappush(self._heap, task)
            self._not_empty.notify()
            return True

    def get(self, block: bool = True, timeout: Optional[float] = None) -> Optional[Task]:
        """
        Get the next task from the queue (highest priority, FIFO within priority).
        Returns None if queue is empty and non-blocking, or on timeout.
        """
        with self._not_empty:
            while len(self._heap) == 0 and not self._closed:
                if not block:
                    return None
                if timeout is not None:
                    if not self._not_empty.wait(timeout):
                        return None
                else:
                    self._not_empty.wait()

            if len(self._heap) == 0 and self._closed:
                return None

            task = heapq.heappop(self._heap)

            # If task was cancelled while pending, skip it and try next
            while task.cancelled or task.task_id in self._cancelled_pending:
                task.state = TaskState.CANCELLED
